# Code generated by engine/cmd/gensdk (make gen) from catalog/catalog.gen.json; DO NOT EDIT.
"""Webhook signature verification against deliveries signed like the gateway signs them."""

from __future__ import annotations

import base64
import hashlib
import hmac
import json
import time
import unittest
from typing import Any, Callable, List

from socialtap import JobEventData, Event, SocialTap, WebhookVerificationError, verify_webhook
from socialtap._webhooks import (
    WEBHOOK_ID_HEADER,
    WEBHOOK_SECRET_PREFIX,
    WEBHOOK_SIGNATURE_HEADER,
    WEBHOOK_SIGNATURE_VERSION,
    WEBHOOK_TIMESTAMP_HEADER,
    WEBHOOK_TOLERANCE_S,
)


class WebhooksTest(unittest.TestCase):
    def test_verify_webhook(self) -> None:
        """verify_webhook accepts a Standard Webhooks signature and rejects tampering, old timestamps and wrong secrets."""
        key = b"0123456789abcdef0123456789abcdef"
        secret = WEBHOOK_SECRET_PREFIX + base64.b64encode(key).decode()
        other = WEBHOOK_SECRET_PREFIX + base64.b64encode(b"other").decode()
        body = json.dumps({"object": "event", "id": "evt_1", "type": "sdk.type_newer_than_this_sdk", "timestamp": "2030-01-01T00:00:00Z", "data": {"a": 1}})
        ts = int(time.time())
        sig = base64.b64encode(hmac.new(key, f"evt_1.{ts}.{body}".encode(), hashlib.sha256).digest()).decode()
        v = WEBHOOK_SIGNATURE_VERSION
        headers = {WEBHOOK_ID_HEADER: "evt_1", WEBHOOK_TIMESTAMP_HEADER: str(ts), WEBHOOK_SIGNATURE_HEADER: f"{v},bogus {v},{sig}"}
        self.assertEqual(verify_webhook(body, headers, secret).id, "evt_1")
        client = SocialTap(api_key="st_live_sdk")
        self.assertEqual(client.webhooks.verify(body.encode(), headers, [other, secret]).id, "evt_1")
        bad: List[Callable[[], Any]] = [
            lambda: verify_webhook(body + " ", headers, secret),
            lambda: verify_webhook(body, headers, other),
            lambda: verify_webhook(body, headers, secret, now=ts + WEBHOOK_TOLERANCE_S + 1),
            lambda: verify_webhook(body, {}, secret),
        ]
        for call in bad:
            with self.assertRaises(WebhookVerificationError):
                call()

    def test_event_data_is_typed(self) -> None:
        """data is the model of the event's type (catalog event_types); a type newer than the SDK keeps its data as a dict."""
        event = Event.from_dict(json.loads("{\"data\":{\"created_at\":\"2030-01-01T00:00:00Z\",\"credits\":{\"charged\":1,\"max\":1,\"reserved\":1},\"finished_at\":\"2030-01-01T00:00:00Z\",\"id\":\"x\",\"metadata\":{\"k\":\"x\"},\"object\":\"job\",\"request_counts\":{\"canceled\":1,\"expired\":1,\"failed\":1,\"queued\":1,\"running\":1,\"succeeded\":1,\"total\":1},\"results_url\":\"x\",\"status\":\"queued\",\"url\":\"x\"},\"id\":\"x\",\"object\":\"event\",\"timestamp\":\"2030-01-01T00:00:00Z\",\"type\":\"job.completed\"}"))
        self.assertIsInstance(event.data, JobEventData)
        newer = {**json.loads("{\"data\":{\"created_at\":\"2030-01-01T00:00:00Z\",\"credits\":{\"charged\":1,\"max\":1,\"reserved\":1},\"finished_at\":\"2030-01-01T00:00:00Z\",\"id\":\"x\",\"metadata\":{\"k\":\"x\"},\"object\":\"job\",\"request_counts\":{\"canceled\":1,\"expired\":1,\"failed\":1,\"queued\":1,\"running\":1,\"succeeded\":1,\"total\":1},\"results_url\":\"x\",\"status\":\"queued\",\"url\":\"x\"},\"id\":\"x\",\"object\":\"event\",\"timestamp\":\"2030-01-01T00:00:00Z\",\"type\":\"job.completed\"}"), "type": "sdk.type_newer_than_this_sdk", "data": {"a": 1}}
        self.assertEqual(Event.from_dict(newer).data, {"a": 1})


if __name__ == "__main__":
    unittest.main()
